export {};

let naiveCalls = 0;
let memoCalls = 0;

function fibNaive(n: number): number {
  naiveCalls++;
  return n < 2 ? n : fibNaive(n - 1) + fibNaive(n - 2);
}

const cache = new Map<number, number>();

function fibMemo(n: number): number {
  memoCalls++;
  // TODO : si n < 2 retourne n ; si le résultat est déjà dans le cache retourne-le ;
  //        sinon calcule-le récursivement avec fibMemo, mémorise-le dans le cache puis retourne-le
  return n < 2 ? n : fibMemo(n - 1) + fibMemo(n - 2);
}

const BUDGET = 100;
fibNaive(20);
fibMemo(20);
console.log(`fib(20) naïf: ${naiveCalls} appels`);
console.log(`fib(20) mémoïsé: ${memoCalls} appels`);
console.log(
  `Budget ${BUDGET} appels: naïf ${naiveCalls > BUDGET ? 'dépasse' : 'respecte'}, mémoïsé ${memoCalls > BUDGET ? 'dépasse' : 'respecte'}`,
);
